sys_script.script:
(function executeRule(current, previous) {
    var gr = new GlideRecord('u_book_issue');
    gr.addQuery('u_reference', current.getUniqueValue());
    gr.setLimit(1);
    gr.query();
    if (gr.hasNext()) {
        gs.addErrorMessage('Cannot delete this Books Request because it has associated Book Issue records. Please close the related Book Issue first.');
        current.setAbortAction(true);
    }
})(current, previous);
